APPROVED_CAPABILITIES = {'search_documents', 'read_document', 'get_issue'}

def approve_capability(name, user_scopes):
    if name not in APPROVED_CAPABILITIES:
        return False, 'capability not approved by host'
    if name == 'read_document' and 'documents:read' not in user_scopes:
        return False, 'missing documents:read scope'
    return True, 'host policy permits capability; validate arguments before execution'
